/**
 * Machine Shift Totals from seeded events and windows.
 * Single source of truth for shift-level machine production totals.
 * Implements TASK 5B §2:
 * - Derived analytically from the same events & windows generated by machineEvents.ts
 * - For current shift, equals rollup of 30s windows
 * - Rejects/reworks integrate rejectStore corrections and baseline
 * - Caches closed shifts permanently, current shift per 30s bucket
 */

import { getShiftTimeline, getMachineProfile, type EventType } from "./machineEvents";
import { type ShiftInfo, type ShiftCode, SHIFT_SECONDS } from "./shiftClock";
import { rejectStore } from "./rejectStore";
import type { MachineTotals } from "./oeeTotals";
import { makeRng } from "./rng";
import { getLineLossFactor } from "./calibration";

const closedShiftCache = new Map<string, MachineTotals>();
const currentShiftCache = new Map<string, { bucket: number; totals: MachineTotals }>();

function computeClosedShiftTotalsFast(
  plantId: string,
  lineId: string,
  machineCode: string,
  shiftInfo: ShiftInfo,
): MachineTotals {
  const profile = getMachineProfile(machineCode);
  const shiftKey = shiftInfo.shiftKey;
  const seed = `${plantId}:${shiftKey}:${machineCode}:this-shift`;
  const rng = makeRng(seed);
  const lossFactor = getLineLossFactor(plantId, lineId);

  const targetEventCount = 11;
  const intervalSpacing = Math.floor((SHIFT_SECONDS - 1800) / targetEventCount);

  type Ev = { startSec: number; endSec: number; type: EventType; speedPct?: number };
  const events: Ev[] = [{ startSec: 0, endSec: 900, type: "planned" }];

  for (let i = 1; i < targetEventCount; i++) {
    const startSec = 1000 + i * intervalSpacing + Math.floor(rng() * 100);
    if (startSec >= SHIFT_SECONDS - 60) break;

    const rType = rng();
    let type: EventType = "minor_stop";
    let durationSec = 30;
    let speedPct: number | undefined;

    if (rType < 0.28) {
      type = "downtime";
      durationSec = Math.max(660, Math.round((700 + Math.floor(rng() * 1000)) * lossFactor * 0.72));
    } else if (rType < 0.6) {
      type = "speed_loss";
      durationSec = Math.round((900 + Math.floor(rng() * 1000)) * lossFactor * 0.82);
      speedPct = Math.max(
        52,
        Math.min(86, Math.round((72 + Math.floor(rng() * 16)) / Math.sqrt(lossFactor))),
      );
    } else if (rType < 0.9) {
      type = "minor_stop";
      durationSec = Math.round((45 + Math.floor(rng() * 180)) * lossFactor * 0.75);
      if (rng() > 0.5) {
        // match rng advancement
      }
    } else {
      type = "planned";
      durationSec = 600 + Math.floor(rng() * 600);
    }

    const endSec = Math.min(SHIFT_SECONDS, startSec + durationSec);
    let effType = type;
    if (effType === "minor_stop" && endSec - startSec > 600) {
      effType = "downtime";
    }
    const evItem: Ev = { startSec, endSec, type: effType };
    if (speedPct !== undefined) {
      evItem.speedPct = speedPct;
    }
    events.push(evItem);
  }

  const targetPerWindow = (profile.idealRatePpm * 30) / 60;
  let pdSec = 0;
  let dSec = 0;
  let msSec = 0;
  let positiveSlSec = 0;
  let runningSec = 0;
  let units = 0;
  let evIdx = 0;

  for (let w = 0; w < 960; w++) {
    const wMid = w * 30 + 15;
    while (evIdx < events.length && (events[evIdx]?.endSec ?? 0) <= wMid) {
      evIdx++;
    }
    const currentEv = events[evIdx];
    const ev =
      currentEv && currentEv.startSec <= wMid && wMid < currentEv.endSec ? currentEv : undefined;

    if (ev) {
      if (ev.type === "planned") {
        pdSec += 30;
      } else if (ev.type === "downtime") {
        dSec += 30;
      } else if (ev.type === "minor_stop") {
        msSec += 30;
      } else if (ev.type === "speed_loss") {
        runningSec += 30;
        const pct = ev.speedPct ?? 78;
        const u = Math.round((targetPerWindow * pct) / 100);
        units += u;
        positiveSlSec += ((targetPerWindow - u) * 30) / targetPerWindow;
      }
    } else {
      runningSec += 30;
      units += Math.round(targetPerWindow);
    }
  }

  const stops = events.filter((e) => e.type === "downtime" || e.type === "minor_stop").length;

  const storeTotals = rejectStore.getTotals(plantId, lineId, shiftInfo.shiftKey, machineCode);
  let reject = 0;
  let rework = 0;

  if (storeTotals.totalReject > 0 || storeTotals.totalRework > 0) {
    reject = storeTotals.totalReject;
    rework = storeTotals.totalRework;
  } else {
    const calibratedRejectRate = Math.min(3.2, Math.max(0.7, 1.7 * Math.sqrt(lossFactor)));
    reject = Math.round((units * calibratedRejectRate) / 100);
    rework = 0;
  }

  return {
    calendarMin: 480,
    naMin: 0,
    usMin: 0,
    pdMin: pdSec / 60,
    dMin: dSec / 60,
    msMin: msSec / 60,
    slPosMin: positiveSlSec / 60,
    slNegMin: 0,
    units,
    reject,
    rework,
    runningMin: runningSec / 60,
    stops,
  };
}

export function clearCurrentShiftCache() {
  currentShiftCache.clear();
}

if (typeof window !== "undefined") {
  rejectStore.subscribe(() => {
    clearCurrentShiftCache();
  });
}

/**
 * Resolves a ShiftInfo structure from an epoch timestamp in milliseconds.
 * Shifts run in WIB (UTC+7):
 * - Shift A: 07:00 - 15:00 WIB
 * - Shift B: 15:00 - 23:00 WIB
 * - Shift C: 23:00 - 07:00 WIB next day
 */
export function resolveShiftInfoFromStartMs(shiftStartMs: number): ShiftInfo {
  const wibMs = shiftStartMs + 7 * 3600000;
  const wib = new Date(wibMs);
  const hour = wib.getUTCHours();
  const code: ShiftCode = hour >= 7 && hour < 15 ? "A" : hour >= 15 && hour < 23 ? "B" : "C";
  const startHour = code === "A" ? 7 : code === "B" ? 15 : 23;
  const endHour = (startHour + 8) % 24;

  let wibDateForDateKey = wib;
  if (code === "C" && hour < 7) {
    wibDateForDateKey = new Date(wibMs - 86400000);
  }

  const dateKey = `${wibDateForDateKey.getUTCFullYear()}-${String(wibDateForDateKey.getUTCMonth() + 1).padStart(2, "0")}-${String(wibDateForDateKey.getUTCDate()).padStart(2, "0")}`;
  const shiftKey = `${dateKey}:${code}`;
  const label = `Shift ${code} · ${String(startHour).padStart(2, "0")}:00-${String(endHour).padStart(2, "0")}:59 WIB`;
  const startSec = Math.floor(shiftStartMs / 1000);
  const endSec = startSec + SHIFT_SECONDS;
  const nowSec = Math.floor(Date.now() / 1000);
  const isCurrent = nowSec >= startSec && nowSec < endSec;
  const elapsedSec = isCurrent
    ? Math.min(SHIFT_SECONDS, Math.max(0, nowSec - startSec))
    : SHIFT_SECONDS;

  return {
    code,
    label,
    startHour,
    endHour,
    dateKey,
    shiftKey,
    startSec,
    endSec,
    elapsedSec,
    isCurrent,
  };
}

/**
 * Gets MachineTotals for a machine across a specific shift from shiftStartMs up to untilMs.
 *
 * @param plantId - e.g. "J2"
 * @param lineId - e.g. "TUP01"
 * @param machineCode - e.g. "LTF01"
 * @param shiftStartMs - shift start epoch in milliseconds
 * @param untilMs - upper bound epoch in milliseconds
 */
export function getMachineShiftTotals(
  plantId: string,
  lineId: string,
  machineCode: string,
  shiftStartMs: number,
  untilMs: number,
): MachineTotals {
  const shiftInfo = resolveShiftInfoFromStartMs(shiftStartMs);
  const shiftEndMs = shiftStartMs + SHIFT_SECONDS * 1000;
  const nowMs = Date.now();
  const nowFloor30s = Math.floor(nowMs / 30000) * 30000;

  let effectiveUntilMs = Math.min(untilMs, shiftEndMs);
  if (shiftInfo.isCurrent && effectiveUntilMs > nowFloor30s) {
    effectiveUntilMs = nowFloor30s;
  }

  const isClosed = !shiftInfo.isCurrent || effectiveUntilMs >= shiftEndMs;
  const closedKey = `${plantId}:${lineId}:${machineCode}:${shiftInfo.shiftKey}`;

  if (isClosed && closedShiftCache.has(closedKey)) {
    return closedShiftCache.get(closedKey)!;
  }

  if (isClosed && effectiveUntilMs >= shiftEndMs) {
    const totals = computeClosedShiftTotalsFast(plantId, lineId, machineCode, shiftInfo);
    closedShiftCache.set(closedKey, totals);
    return totals;
  }

  const untilBucket = Math.floor(effectiveUntilMs / 30000) * 30000;
  const currentKey = `${plantId}:${lineId}:${machineCode}:${shiftInfo.shiftKey}:${untilBucket}`;

  if (!isClosed) {
    const cached = currentShiftCache.get(currentKey);
    if (cached && cached.bucket === untilBucket) {
      return cached.totals;
    }
  }

  const profile = getMachineProfile(machineCode);
  const elapsedSec = Math.min(
    SHIFT_SECONDS,
    Math.max(0, Math.floor((effectiveUntilMs - shiftStartMs) / 1000)),
  );
  const revealedSec = Math.floor(elapsedSec / 30) * 30;

  const timeline = getShiftTimeline(machineCode, shiftInfo, revealedSec, plantId, "this-shift");
  const numWindows = Math.floor(revealedSec / 30);

  const naSec = 0;
  const usSec = 0;
  let pdSec = 0;
  let dSec = 0;
  let msSec = 0;
  let positiveSlSec = 0;
  let negativeSlSec = 0;
  let units = 0;
  let runningSec = 0;

  for (let i = 0; i < numWindows; i++) {
    const w = timeline.windows[i];
    if (!w) break;

    if (w.type === "planned") {
      pdSec += 30;
    } else if (w.type === "downtime") {
      dSec += 30;
    } else if (w.type === "minor_stop") {
      msSec += 30;
    } else if (w.type === "speed_loss") {
      runningSec += 30;
      units += w.output;
      const target = w.targetOutput > 0 ? w.targetOutput : (profile.idealRatePpm * 30) / 60;
      if (w.output < target) {
        positiveSlSec += ((target - w.output) * 30) / target;
      } else if (w.output > target) {
        negativeSlSec += ((w.output - target) * 30) / target;
      }
    } else {
      runningSec += 30;
      units += w.output;
    }
  }

  const stopEvents = timeline.events.filter(
    (e) => (e.type === "downtime" || e.type === "minor_stop") && e.startSec < revealedSec,
  );
  const stops = stopEvents.length;

  // Rejects & reworks
  const storeTotals = rejectStore.getTotals(plantId, lineId, shiftInfo.shiftKey, machineCode);
  let reject = 0;
  let rework = 0;

  if (storeTotals.totalReject > 0 || storeTotals.totalRework > 0) {
    reject = storeTotals.totalReject;
    rework = storeTotals.totalRework;
  } else {
    const lossFactor = getLineLossFactor(plantId, lineId);
    const calibratedRejectRate = Math.min(3.2, Math.max(0.7, 1.7 * Math.sqrt(lossFactor)));
    reject = Math.round((units * calibratedRejectRate) / 100);
    rework = 0;
  }

  const totals: MachineTotals = {
    calendarMin: (numWindows * 30) / 60,
    naMin: naSec / 60,
    usMin: usSec / 60,
    pdMin: pdSec / 60,
    dMin: dSec / 60,
    msMin: msSec / 60,
    slPosMin: positiveSlSec / 60,
    slNegMin: negativeSlSec / 60,
    units,
    reject,
    rework,
    runningMin: runningSec / 60,
    stops,
  };

  if (isClosed) {
    closedShiftCache.set(closedKey, totals);
  } else {
    currentShiftCache.set(currentKey, { bucket: untilBucket, totals });
  }

  return totals;
}
